"""Load the built-in model catalog (``catalog.yaml``, generated by scripts/refresh_catalog.py)."""

import difflib
import logging
from functools import cache
from importlib import resources
from typing import Any

import yaml

from brasskey.errors import BrasskeyError
from brasskey.models.types import Catalog, CatalogModel

logger = logging.getLogger(__name__)

CATALOG_FILE = "catalog.yaml"


class UnknownModelError(BrasskeyError):
    default_code = "BK-E-UNKNOWN-MODEL"


@cache
def load_catalog() -> Catalog:
    """The catalog shipped with this version of Brasskey (validated, cached)."""
    text = resources.files("brasskey.models").joinpath(CATALOG_FILE).read_text(encoding="utf-8")
    data: Any = yaml.safe_load(text)
    catalog = Catalog.model_validate(data)
    logger.debug("Catalog: %d models (generated %s)", len(catalog.models), catalog.generated_at)
    return catalog


def find_model(catalog: Catalog, model_id: str) -> CatalogModel:
    """A catalog model by id (case-insensitive), or a plain error with suggestions."""
    wanted = model_id.strip().lower()
    for model in catalog.models:
        if model.id == wanted:
            return model
    ids = [model.id for model in catalog.models]
    close = difflib.get_close_matches(wanted, ids, n=1)
    hint = f" Did you mean {close[0]}?" if close else ""
    raise UnknownModelError(
        f"'{model_id}' isn't in the Brasskey catalog.{hint}",
        fix=f"Use one of: {', '.join(ids)}; or any Hugging Face model as hf:org/name.",
    )
